/*
 * headless_point_verbs.c - Point processor verb implementations
 *
 * Originally generated by tools/kernelverbs_parser/generate_processor_stubs.py,
 * now contains hand-written implementations for point manipulation verbs.
 *
 * DO NOT regenerate - this file contains production implementations.
 *
 * Implementation status:
 * - point.set: COMPLETE - Create point from h,v coordinates
 * - point.get: COMPLETE - Extract h,v coordinates from point
 */

#include "frontier.h"
#include "standard.h"

#include "memory.h"
#include "strings.h"
#include "lang.h"
#include "langinternal.h"
#include "tablestructure.h"

/* Token enum for all verbs in the point processor */
enum {
    poiv_get = 0,
    poiv_set = 1
};

static boolean point_valueproc(short token, hdltreenode hparam1,
                                     tyvaluerecord *vreturned,
                                     bigstring bserror) {
    switch(token) {
        case poiv_get: {
            /* @IMPLEMENTED point.get (point, @h, @v) - Extract h,v from point */
            Point pt;

            /* Get the point parameter */
            if (!getpointvalue(hparam1, 1, &pt))
                return false;

            /* Set horizontal coordinate into address parameter 2 */
            if (!setintvarparam(hparam1, 2, pt.h))
                return false;

            flnextparamislast = true;

            /* Set vertical coordinate into address parameter 3 */
            if (!setintvarparam(hparam1, 3, pt.v))
                return false;

            /* Return true to indicate success */
            (*vreturned).data.flvalue = true;
            return true;
        }

        case poiv_set: {
            /* @IMPLEMENTED point.set (h, v) - Create point from coordinates */
            Point pt;

            /* Get horizontal coordinate */
            if (!getintvalue(hparam1, 1, &pt.h))
                return false;

            flnextparamislast = true;

            /* Get vertical coordinate */
            if (!getintvalue(hparam1, 2, &pt.v))
                return false;

            /* Return the point value */
            setpointvalue(pt, vreturned);
            return true;
        }

        default:
            return false;
    }
}

boolean pointinitverbs(void) {
    hdlhashtable htable = nil;
    bigstring bsname;

    copystring(BIGSTRING("\ppoint"), bsname);

    if (!newfunctionprocessor(bsname, &point_valueproc, false, &htable))
        return false;

    pushhashtable(htable);

    #define ADD_VERB(name, tok) do { \
        bigstring bs; \
        copystring(name, bs); \
        if (!langaddkeyword(bs, tok)) { \
            pophashtable(); \
            return false; \
        } \
    } while(0)

    ADD_VERB(BIGSTRING("\pget"), poiv_get);
    ADD_VERB(BIGSTRING("\pset"), poiv_set);

    #undef ADD_VERB

    pophashtable();
    return true;
}
